import{z as s,x as i,o as B,c as d,q as t,j as o,D as A,d as e,s as n,S as l,b as a}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"QE 的理论","description":"","frontmatter":{"title":"QE 的理论","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/mt-qe-theory.md","filePath":"econ/mt-qe-theory.md","lastUpdated":1791413859000}'),p={name:"econ/mt-qe-theory.md"};function D(C,E,F,m,c,f){const r=i("Mermaid");return B(),d("div",null,[E[2]||(E[2]=t('<h1 id="qe-的理论" tabindex="-1">QE 的理论 <a class="header-anchor" href="#qe-的理论" aria-label="Permalink to &quot;QE 的理论&quot;">​</a></h1><div class="epigraph"><p>在无摩擦的市场里，公开市场操作只是资产互换；QE 的每一种效果，都必须指名道姓地找到那个被它松开的摩擦。</p><footer>—— 据 Wallace 1981；Eggertsson–Woodford 2003 整理</footer></div><p><a href="/econ/mt-expectations-transmission">上一课</a>把传导拆成利率路径、锚定与家庭结构三段，其中每一段都还需要一个正常工作的短端利率。利率触到下限时（<a href="/econ/zlb-unconventional">零下限与非常规政策</a>），常规边际消失，工具转向央行资产负债表本身。<a href="/econ/qe-forward-guidance">QE 与前瞻指引</a>与<a href="/econ/central-bank-balance-sheet">央行资产负债表</a>已给出操作方式与事件研究证据；本课补它们背后的理论：QE 在什么模型里严格等于什么，以及它的无关性基准。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>理论起点是一个反直觉的定理。Wallace 1981 给公开市场操作写了一个 Modigliani–Miller 式的结论：若市场完全、无参与约束、税收一次性，央行用准备金换任何资产，公众都可以无成本地重新组合回原配置——一切公开市场操作都是中性的，无论买的是短债还是长债。这不是对 QE 的否定，而是纪律：<strong>QE 的每一种效果，必须由一个具体摩擦来承担</strong>。理论工作因此不是论证「QE 有效」，而是找到那个摩擦，并说明它何时重要、何时消失。</p><p><span class="marginnote">直觉类比：央行用准备金换长债，像把左口袋的钱挪到右口袋——若两边随时可互换、无成本，口袋的分配无所谓。无关性定理说的正是：没有摩擦时，这种「换」什么也改变不了。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三个摩擦，各自给出一个渠道，可以逐一检验。</p><p><strong>期限生境</strong>：一部分投资者只愿意持有特定期限的资产（养老金匹配久期、监管约束），该期限的供给变化直接改价格。央行买走长期债，生境里的供给被抽走，期限溢价压缩。事件研究按渠道分解总效应时，这一渠道的可检验含义是：被购买的品种压得更多——抵押支持证券的收益率反应大于同期限国债。</p><p><span class="marginnote">「期限生境」翻译成大白话：有些买家只吃某一种期限的债券——养老金必须买长债去匹配几十年后的支出。央行从这块「栖息地」抽走长债，那里的价格就只能涨（收益率跌）；别的期限未必跟着动。</span></p><p><strong>中介约束</strong>：银行与非银中介受杠杆与融资约束，危机中约束收紧、信贷收缩（<a href="/econ/gertler-kiyotaki">Gertler–Kiyotaki</a> 的脉络）。央行直接购买替代了收缩的中介资产负债表，等于把自身的无约束表借给市场使用；Gertler–Karadi 2011 把这一渠道写成可校准的模型。</p><p><strong>信号与承诺</strong>：Eggertsson–Woodford 2003 指出，下限上真正稀缺的不是资产购买力，而是可信的未来低利率承诺；长期债购买把央行自己的表押进未来，提前退出的成本变高，承诺被部分抵押。QE 在这里的价值不是买什么，而是「买了」这个行为对承诺可信性的贡献。</p>',12)),(B(),o(l,null,{default:A(()=>[n(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20BASE%5B%22%E6%97%A0%E6%91%A9%E6%93%A6%E5%9F%BA%E5%87%86%EF%BC%9A%E6%93%8D%E4%BD%9C%E4%B8%AD%E6%80%A7%22%5D%20--%3E%20F1%7B%22%E5%93%AA%E4%B8%AA%E6%91%A9%E6%93%A6%22%7D%0A%20%20F1%20--%3E%7C%22%E6%9C%9F%E9%99%90%E5%81%8F%E5%A5%BD%E9%9B%86%E4%B8%AD%22%7C%20HAB%5B%22%E7%94%9F%E5%A2%83%E6%B8%A0%E9%81%93%EF%BC%9A%E6%9C%9F%E9%99%90%E6%BA%A2%E4%BB%B7%E5%8E%8B%E7%BC%A9%22%5D%0A%20%20F1%20--%3E%7C%22%E4%B8%AD%E4%BB%8B%E6%9D%A0%E6%9D%86%E7%BA%A6%E6%9D%9F%22%7C%20MED%5B%22%E4%B8%AD%E4%BB%8B%E6%B8%A0%E9%81%93%EF%BC%9A%E4%BF%A1%E8%B4%B7%E4%BE%9B%E7%BB%99%E6%81%A2%E5%A4%8D%22%5D%0A%20%20F1%20--%3E%7C%22%E6%89%BF%E8%AF%BA%E4%B8%8D%E5%8F%AF%E4%BF%A1%22%7C%20SIG%5B%22%E4%BF%A1%E5%8F%B7%E6%B8%A0%E9%81%93%EF%BC%9A%E6%9C%AA%E6%9D%A5%E4%BD%8E%E5%88%A9%E7%8E%87%E8%A2%AB%E6%8A%B5%E6%8A%BC%22%5D%0A%20%20HAB%20--%3E%20TEST%5B%22%E5%8F%AF%E6%A3%80%E9%AA%8C%EF%BC%9A%E8%A2%AB%E8%B4%AD%E5%93%81%E7%A7%8D%E6%94%B6%E7%9B%8A%E5%8E%8B%E5%BE%97%E6%9B%B4%E5%A4%9A%22%5D%0A%20%20MED%20--%3E%20TEST%0A%20%20SIG%20--%3E%20TEST%0A"})]),fallback:A(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,"三个渠道的相对权重决定 QE 的边界，也解释了证据里的争议。生境渠道是价格效应，随购买停止而回吐；中介渠道是数量效应，取决于约束是否仍然紧；信号渠道与前瞻指引不可分离——它本就是指引的执行手段。归因困难由此而来：事件研究测得的是三渠道之和，而其中一段（信号）恰恰依赖市场对未来政策的预期，反事实无法直接观测。",-1)),E[5]||(E[5]=a("p",null,[e("Eggertsson–Woodford 2003 留下一个可作判别式的悖论：若市场本就相信承诺，购买只是资产互换，净效应趋近零；若承诺不可信，购买的价值恰在于让它可信。"),a("strong",null,"QE 的效果与它自身的必要性成正比"),e("——必要时的效果恰好最大，这也意味着用繁荣期数据外推危机期的 QE 效果会系统性偏低。")],-1)),E[6]||(E[6]=a("p",null,[a("span",{class:"marginnote"},"无关性定理不是摆设：它同时解释了为什么常规公开市场操作（买短债）在正常时期无须争论，以及为什么 QE 的辩护必须落在摩擦上。没有指名摩擦的「流动性注入」论证，在 Wallace 1981 面前是空话。")],-1)),E[7]||(E[7]=a("p",null,[a("span",{class:"marginnote"},"常见误区：拿繁荣期的数据说「QE 没什么用」。恰恰相反——繁荣期承诺本就可信，QE 只剩资产互换，效应趋近零；危机期承诺失灵时效应才最大。用错时期的数据会系统性低估 QE。")],-1)),(B(),o(l,null,{default:A(()=>[n(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20BUY%5B%22%E5%A4%AE%E8%A1%8C%E5%AE%A3%E5%B8%83%E9%95%BF%E6%9C%9F%E8%B4%AD%E4%B9%B0%22%5D%20--%3E%20Q%7B%22%E5%B8%82%E5%9C%BA%E6%9C%AC%E5%B0%B1%E7%9B%B8%E4%BF%A1%E4%BD%8E%E5%88%A9%E7%8E%87%E6%89%BF%E8%AF%BA%EF%BC%9F%22%7D%0A%20%20Q%20--%20%22%E7%9B%B8%E4%BF%A1%22%20--%3E%20SWAP%5B%22%E8%B4%AD%E4%B9%B0%E5%8F%AA%E6%98%AF%E8%B5%84%E4%BA%A7%E4%BA%92%E6%8D%A2%EF%BC%8C%E5%87%80%E6%95%88%E5%BA%94%E8%B6%8B%E8%BF%91%E9%9B%B6%22%5D%0A%20%20Q%20--%20%22%E4%B8%8D%E4%BF%A1%22%20--%3E%20MORT%5B%22%E8%B4%AD%E4%B9%B0%E6%8A%8A%E5%A4%AE%E8%A1%8C%E7%9A%84%E8%A1%A8%E6%8A%BC%E8%BF%9B%E6%9C%AA%E6%9D%A5%22%5D%0A%20%20MORT%20--%3E%20CRED%5B%22%E6%8F%90%E5%89%8D%E9%80%80%E5%87%BA%E6%88%90%E6%9C%AC%E5%8D%87%E9%AB%98%EF%BC%8C%E6%89%BF%E8%AF%BA%E8%A2%AB%E6%8A%B5%E6%8A%BC%22%5D%0A%20%20CRED%20--%3E%20BIG%5B%22%E6%AD%A4%E6%97%B6%20QE%20%E6%95%88%E6%9E%9C%E6%9C%80%E5%A4%A7%22%5D%0A%20%20SWAP%20--%3E%20PARA%5B%22%E6%95%88%E6%9E%9C%E4%B8%8E%E5%BF%85%E8%A6%81%E6%80%A7%E6%88%90%E6%AD%A3%E6%AF%94%22%5D%0A%20%20BIG%20--%3E%20PARA%0A"})]),fallback:A(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[8]||(E[8]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>财政是绕不开的另一侧。Sargent–Wallace 1981 的不愉快算术与<a href="/econ/ftpl">物价水平的财政理论</a>划定边界：若财政赤字路径独立于货币当局，央行扩表最终要被财政回填，通胀的决定权移向财政（<a href="/econ/fiscal-monetary-dominance">财政-货币主导</a>）。缩表也不是扩表的镜像——退出路径本身有再定价效应，<a href="/econ/central-bank-balance-sheet">央行资产负债表</a>的递增上限设计即为此。下一课转向负债侧更激进的创新：央行不再买资产，而是直接对公众发行负债。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>无关性基准：完全市场下一切公开市场操作中性，QE 效果必须落到具体摩擦。</li><li>三渠道分工：期限生境改溢价，中介约束改信贷供给，信号渠道抵押承诺。</li><li>QE 的效果与自身必要性成正比，事件研究归因因此系统性困难。</li><li>财政主导划定 QE 的最终边界：扩表要被财政回填时，通胀决定权移向财政。</li><li>出处：Wallace 1981；Eggertsson–Woodford 2003；Gertler–Karadi 2011；Krishnamurthy–Vissing-Jorgensen 2011；Sargent–Wallace 1981。</li></ul>',4))])}const u=s(p,[["render",D]]);export{g as __pageData,u as default};
